-- Amounts are whole yen (bigint). Ids are UUID v7 generated by the application, so ordering by id is ordering by
-- creation time. Status-like columns are text with CHECK constraints rather than enum types, which are awkward
-- to change in later migrations.

CREATE TABLE customers (
    id           uuid PRIMARY KEY,
    name         text NOT NULL CONSTRAINT customers_name_length CHECK (char_length(name) BETWEEN 1 AND 200),
    name_kana    text NOT NULL CONSTRAINT customers_name_kana_length CHECK (char_length(name_kana) BETWEEN 1 AND 200),
    fee_deducted boolean NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now()
);

-- Every normalized payer name that identifies a customer: the customer's own kana name (source = 'kana') and
-- the aliases added by hand or learned from a confirmed match. One table and one unique index, so a payer name
-- can never point at two customers.
CREATE TABLE customer_aliases (
    id               uuid PRIMARY KEY,
    customer_id      uuid NOT NULL REFERENCES customers (id),
    alias_raw        text NOT NULL,
    alias_normalized text NOT NULL CONSTRAINT customer_aliases_normalized_not_empty CHECK (alias_normalized <> ''),
    source           text NOT NULL CONSTRAINT customer_aliases_source CHECK (source IN ('kana', 'manual', 'learned')),
    created_at       timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT customer_aliases_normalized_key UNIQUE (alias_normalized)
);
CREATE INDEX customer_aliases_customer_idx ON customer_aliases (customer_id);

CREATE TABLE invoices (
    id             uuid PRIMARY KEY,
    customer_id    uuid NOT NULL CONSTRAINT invoices_customer_fkey REFERENCES customers (id),
    invoice_number text NOT NULL CONSTRAINT invoices_number_length CHECK (char_length(invoice_number) BETWEEN 1 AND 50),
    amount         bigint NOT NULL CONSTRAINT invoices_amount_positive CHECK (amount > 0),
    due_date       date NOT NULL,
    status         text NOT NULL DEFAULT 'open' CONSTRAINT invoices_status CHECK (status IN ('open', 'cleared')),
    created_at     timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT invoices_number_key UNIQUE (invoice_number)
);
CREATE INDEX invoices_open_by_customer_idx ON invoices (customer_id, due_date, id) WHERE status = 'open';
CREATE INDEX invoices_open_by_amount_idx ON invoices (amount, due_date, id) WHERE status = 'open';

-- One row per accepted import request. The key and the hash of the request make a repeated request a no-op.
CREATE TABLE payment_batches (
    id              uuid PRIMARY KEY,
    idempotency_key text NOT NULL,
    request_hash    bytea NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT payment_batches_idempotency_key_key UNIQUE (idempotency_key)
);

CREATE TABLE payments (
    id                    uuid PRIMARY KEY,
    batch_id              uuid NOT NULL REFERENCES payment_batches (id),
    line_no               integer NOT NULL CONSTRAINT payments_line_no_positive CHECK (line_no >= 1),
    paid_on               date NOT NULL,
    amount                bigint NOT NULL CONSTRAINT payments_amount_positive CHECK (amount > 0),
    payer_name_raw        text NOT NULL,
    -- Empty when the name could not be normalized.
    payer_name_normalized text NOT NULL,
    status                text NOT NULL CONSTRAINT payments_status CHECK (status IN ('unmatched', 'suggested', 'matched')),
    -- What the automatic matching decided at import time and why (rule, invoices, reason).
    decision              jsonb NOT NULL,
    created_at            timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT payments_batch_line_key UNIQUE (batch_id, line_no)
);
CREATE INDEX payments_status_idx ON payments (status, id);

CREATE TABLE matches (
    id           uuid PRIMARY KEY,
    payment_id   uuid NOT NULL REFERENCES payments (id),
    rule         text NOT NULL CONSTRAINT matches_rule CHECK (rule IN ('R1', 'R2', 'R3', 'R4', 'manual')),
    state        text NOT NULL CONSTRAINT matches_state CHECK (state IN ('suggested', 'confirmed', 'cancelled')),
    fee_amount   bigint NOT NULL DEFAULT 0 CONSTRAINT matches_fee_not_negative CHECK (fee_amount >= 0),
    created_at   timestamptz NOT NULL DEFAULT now(),
    confirmed_at timestamptz,
    cancelled_at timestamptz
);
-- Invariant I1: a payment has at most one match that is not cancelled. Cancelled matches stay as history.
CREATE UNIQUE INDEX matches_one_active_per_payment_idx ON matches (payment_id) WHERE state <> 'cancelled';
CREATE INDEX matches_payment_idx ON matches (payment_id, id);

-- The cash of the payment applied to each invoice. For a confirmed match:
--   sum(amount) = payments.amount  and  sum(amount) + matches.fee_amount = sum(invoices.amount)
CREATE TABLE match_allocations (
    match_id   uuid NOT NULL REFERENCES matches (id),
    invoice_id uuid NOT NULL REFERENCES invoices (id),
    amount     bigint NOT NULL CONSTRAINT match_allocations_amount_positive CHECK (amount > 0),
    PRIMARY KEY (match_id, invoice_id)
);
CREATE INDEX match_allocations_invoice_idx ON match_allocations (invoice_id);
